from ljs import *
subject('csharp', 'C#', 'csharp', 'lang', 'Language-specific practice: Console I/O, arrays and List<T>, strings, LINQ and Dictionary, classes and interfaces.')
Ax = ar(-9, 20, 1, 10)
def lkp(l):
    n = int(l[0]); d = dict(x.split() for x in l[1:1 + n]); q = int(l[1 + n]); return '\n'.join(d.get(k, 'MISSING') for k in l[2 + n:2 + n + q])


